changeSet.sql:
SET lock_timeout = '30s';
DROP INDEX CONCURRENTLY IF EXISTS nexus.idx_ta_tenant_source_collection_id;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_ta_tenant_source_collection_id
    ON nexus.topic_assignments (tenant_id, source_collection_id);
RESET lock_timeout;

SET lock_timeout = '30s';
DROP INDEX CONCURRENTLY IF EXISTS nexus.idx_doc_aspects_collection_id;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_doc_aspects_collection_id
    ON nexus.document_aspects (tenant_id, collection_id);
RESET lock_timeout;

SET lock_timeout = '30s';
DROP INDEX CONCURRENTLY IF EXISTS nexus.idx_topics_tenant_collection_id;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_topics_tenant_collection_id
    ON nexus.topics (tenant_id, collection_id);
RESET lock_timeout;

SET lock_timeout = '30s';
DROP INDEX CONCURRENTLY IF EXISTS nexus.idx_taxonomy_meta_tenant_collection_id;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_taxonomy_meta_tenant_collection_id
    ON nexus.taxonomy_meta (tenant_id, collection_id);
RESET lock_timeout;

SET lock_timeout = '30s';
DROP INDEX CONCURRENTLY IF EXISTS nexus.idx_doc_highlights_collection_id;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_doc_highlights_collection_id
    ON nexus.document_highlights (tenant_id, collection_id);
RESET lock_timeout;

SET lock_timeout = '30s';
DROP INDEX CONCURRENTLY IF EXISTS nexus.idx_canary_query_ring_collection_id;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_canary_query_ring_collection_id
    ON nexus.canary_query_ring (tenant_id, collection_id);
RESET lock_timeout;

SET LOCAL lock_timeout = '5s';
DO $q$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL
       AND EXISTS (SELECT 1 FROM pg_attribute a
                    WHERE a.attrelid = to_regclass('nexus.aspect_extraction_queue') AND a.attname = 'collection_id' AND NOT a.attisdropped) THEN
        CREATE INDEX IF NOT EXISTS idx_aspect_queue_collection_id ON nexus.aspect_extraction_queue (tenant_id, collection_id);
    END IF;
END
$q$;
